import { MuscleGroup } from '@prisma/client'
import type {
	ExerciseEquipment,
	ExerciseMechanic,
	MovementPattern,
} from '@sunsteel/contracts'

/**
 * The exercise catalog, the single source for `add-exercises.ts` (idempotent
 * seed, upserted by name) and for the EXER-09 metadata backfill migration,
 * whose UPDATE statements are generated by `buildExerciseMetadataSql` and
 * checked against this list by `scripts/exercise-catalog.test.ts`.
 *
 * Metadata (EXER-09):
 * - `movementPattern` and `mechanic` classify the movement for catalog
 *   browsing, alternatives and routine quality summaries.
 * - `equipmentRequired` lists everything needed to perform it, in the closed
 *   `EXERCISE_EQUIPMENT` vocabulary. `equipment` stays the primary implement.
 * - `substitutionGroup` names near-identical exercises that can replace each
 *   other without changing the training intent. Broader alternatives come from
 *   `movementPattern` plus primary muscles.
 * Instructions and media are content work (EXER-03/EXER-04) and stay empty.
 */
export type ExerciseSeed = {
	name: string
	primaryMuscles: MuscleGroup[]
	secondaryMuscles: MuscleGroup[]
	equipment: string
	movementPattern: MovementPattern
	mechanic: ExerciseMechanic
	equipmentRequired: ExerciseEquipment[]
	substitutionGroup: string
}

