const quote = (value: string) => `'${value.replace(/'/g, "''")}'`

/**
 * Idempotent UPDATE statements that backfill EXER-09 metadata onto existing
 * catalog rows by name. Pasted verbatim into the backfill migration; the
 * catalog test fails if the migration drifts from this output.
 */
export function buildExerciseMetadataSql(
	catalog: readonly ExerciseSeed[] = EXERCISE_CATALOG,
): string[] {
	return catalog.map(
		exercise =>
			`UPDATE "Exercise" SET "movementPattern" = ${quote(exercise.movementPattern)}::"MovementPattern", "mechanic" = ${quote(exercise.mechanic)}::"ExerciseMechanic", "equipmentRequired" = ARRAY[${exercise.equipmentRequired.map(quote).join(', ')}]::TEXT[], "substitutionGroup" = ${quote(exercise.substitutionGroup)} WHERE "name" = ${quote(exercise.name)};`,
	)
}
